{
  "items": [
    {
      "title": "Deutschland in Daten – Historical Statistics Dataset (1834–2018)",
      "url_or_doi": "https://www.deutschland-in-daten.de/datensatz/",
      "justification": "A comprehensive historical dataset containing annual statistical time series on Germany, including leisure, tourism, culture, and sport during the 1960s. It provides separate data for West Germany (Federal Republic of Germany) and East Germany (German Democratic Republic). Particularly useful for examining long-term changes in tourism, sports participation, cultural consumption, and recreational activities. The dataset is available for download."
    },
    {
      "title": "Deutschland in Daten – Culture, Tourism and Sport",
      "url_or_doi": "https://www.deutschland-in-daten.de/kultur-tourismus-und-sport/",
      "justification": "A specialized collection of historical statistics on leisure, tourism, and sport in Germany. Includes data on sports clubs, membership numbers, tourism, cinemas, theaters, and other cultural activities. Contains observations from the 1960s, including sports club membership figures for 1963 in both East and West Germany. Particularly valuable for comparing recreational activities and sports development across the two German states."
    },
    {
      "title": "Deutschland in Daten – Historical Statistics Documentation (1834–2018)",
      "url_or_doi": "https://doi.org/10.12759/hsr.trans.32.v01.2023",
      "justification": "A scholarly historical statistics resource providing detailed documentation, statistical tables, and graphical representations of German historical time series. Covers tourism, leisure, culture, and sports indicators during the 1960s. Includes original sources, methodological explanations, and information about geographical coverage. Useful for researchers requiring traceable historical data and reliable citations."
    },
    {
      "title": "Deutschland in Daten – Historical Sports Clubs and Membership Statistics",
      "url_or_doi": "https://www.deutschland-in-daten.de/kultur-tourismus-und-sport/",
      "justification": "Contains historical statistics on the number of sports clubs and registered members in Germany, including observations for 1963. Provides information about football, athletics, and gymnastics organizations, with membership figures differentiated by sex. Includes separate figures for East and West Germany, enabling comparisons of organized sports participation during the 1960s. Particularly relevant for studying the expansion of mass sports and recreational associations."
    },
    {
      "title": "Deutschland in Daten – Culture and Tourism Historical Time Series",
      "url_or_doi": "https://www.deutschland-in-daten.de/en/culture-and-tourism/",
      "justification": "An English-language resource presenting historical statistical series on cultural activities, leisure, and tourism in Germany. Includes indicators covering the 1960s, such as cinema attendance, cultural institutions, tourism development, and recreational activities. Discusses differences between East and West Germany and provides historical context for the expansion of mass tourism and leisure consumption."
    },
    {
      "title": "GESIS – Reiseanalyse: Historical German Travel Survey Data",
      "url_or_doi": "https://reiseanalyse.de/en/download-area/gesis/",
      "justification": "Provides access information for historical German travel survey datasets preserved in the GESIS Data Archive. The surveys examine holiday behavior, travel destinations, trip duration, accommodation preferences, and other aspects of tourism. A valuable source for historical tourism research, although the availability of individual datasets from the 1960s must be checked in the archive. Some datasets may require registration or research access."
    },
    {
      "title": "Federal Statistical Office – Tourism Statistics, 1960",
      "url_or_doi": "https://www.statistischebibliothek.de/",
      "justification": "The German Federal Statistical Office's digital statistical library preserves historical issues of Wirtschaft und Statistik, including publications from 1960. These contain numerical tables on tourist arrivals, overnight stays, domestic and international visitors, and accommodation. Particularly useful for reconstructing tourism patterns in West Germany at the beginning of the 1960s. Historical tables may require extraction from digitized publications."
    },
    {
      "title": "Federal Statistical Office – Holiday and Recreational Travel Survey, 1969",
      "url_or_doi": "https://www.statistischebibliothek.de/",
      "justification": "Historical tourism statistics published in Wirtschaft und Statistik in November 1970 include results from a household survey covering holiday and recreational trips undertaken between October 1968 and September 1969. The survey recorded travel destinations, accommodation types, transportation methods, and expenditures. The publication also identifies comparable earlier surveys conducted in 1962 and 1966, making it especially relevant for studying changes in West German holiday behavior during the 1960s."
    },
    {
      "title": "Federal Statistical Office – Historical Tourism Accommodation Statistics, 1967–1969",
      "url_or_doi": "https://www.statistischebibliothek.de/",
      "justification": "Historical issues of Wirtschaft und Statistik contain tourism accommodation tables covering the late 1960s. Available indicators include overnight stays in hotels, guesthouses, recreational homes, private accommodation, and health establishments. Statistics also distinguish visitors by country of origin. Useful for analyzing seasonal tourism, accommodation infrastructure, and international tourism in West Germany during 1967–1969."
    },
    {
      "title": "GESIS – Social Science Data Archive: Leisure and Tourism",
      "url_or_doi": "https://www.gesis.org/en/services/finding-and-accessing-data/browse",
      "justification": "GESIS provides access to archived German social science surveys covering leisure activities, cultural participation, tourism, and recreational behavior. The archive is a useful discovery platform for historical studies of everyday life and leisure in East and West Germany. Researchers can search for surveys conducted during the 1960s and investigate available questionnaires, documentation, and microdata. Not every collection covers the requested decade."
    },
    {
      "title": "German Democratic Republic – Statistical Yearbook 1964",
      "url_or_doi": "https://www.gvoon.de/statistisches-jahrbuch-ddr-1964/seite-469-784423.html",
      "justification": "A digitized page from the official 1964 Statistical Yearbook of the German Democratic Republic. The yearbook is a historical source for quantitative information about East German society and economic activity, with potentially relevant sections covering tourism, cultural institutions, recreation, and organized sport. It can complement West German statistical records when examining leisure and tourism in divided Germany. The linked page is part of the yearbook rather than a standalone downloadable dataset."
    },
    {
      "title": "Deutschland in Daten – Historical Statistics on Cinema, Theater and Cultural Leisure",
      "url_or_doi": "https://www.deutschland-in-daten.de/datensatz/",
      "justification": "The historical statistics dataset includes annual time series related to cinemas, theaters, books, libraries, and cultural participation. These indicators provide quantitative evidence about leisure opportunities and entertainment consumption in Germany during the 1960s. The distinction between East and West Germany makes the data useful for studying differences in cultural provision and recreational infrastructure during the Cold War."
    }
  ]
}
